package com.sumax.launcher;
import android.app.*; import android.os.*; import android.content.*; import android.content.pm.*; import android.graphics.*; import android.view.*; import android.widget.*;
public class MainActivity extends Activity {
 String[] modes={"Hunter","Shadow","Guardian"}; int mode=1; android.speech.tts.TextToSpeech speech; boolean speechReady; AssistantView avatar; TextView state;
 public void onCreate(Bundle b){super.onCreate(b); mode=getPreferences(0).getInt("mode",1); speech=new android.speech.tts.TextToSpeech(this,s->{speechReady=s==android.speech.tts.TextToSpeech.SUCCESS;if(speechReady&&speech!=null)speech.setOnUtteranceProgressListener(new android.speech.tts.UtteranceProgressListener(){public void onStart(String id){runOnUiThread(()->{if(avatar!=null&&!isDestroyed())avatar.setSpeaking(true);});}public void onDone(String id){stopPulse();}public void onError(String id){stopPulse();}private void stopPulse(){runOnUiThread(()->{if(avatar!=null&&!isDestroyed())avatar.setSpeaking(false);});}});}); LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setGravity(Gravity.CENTER);root.setPadding(24,48,24,48);root.setBackgroundColor(0xff080e20);
 TextView title=new TextView(this);title.setText("S U M A X");title.setTextSize(28);title.setTextColor(0xff75eaff);root.addView(title); AssistantView assistant=new AssistantView(this); avatar=assistant; assistant.setMode(mode); root.addView(assistant,new LinearLayout.LayoutParams(-1,0,1.2f));
 View reactor=new View(this){Paint p=new Paint(3); protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(x,y)*.8f; p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(5);p.setColor(0xff35dfff);c.drawCircle(x,y,r,p);c.drawCircle(x,y,r*.72f,p);p.setColor(0xffa28bff);float a=SystemClock.uptimeMillis()%4000/4000f*360;c.drawArc(x-r,y-r,x+r,y+r,a,85,false,p);p.setStyle(Paint.Style.FILL);p.setColor(0xff75eaff);c.drawCircle(x,y,r*.18f,p);if(isShown())postInvalidateDelayed(33);}};
 root.addView(reactor,new LinearLayout.LayoutParams(-1,0,1));TextView status=new TextView(this);state=status; status.setTextColor(-1);status.setTextSize(20);status.setText(modes[mode]+" • Ready");root.addView(status); reactor.setOnClickListener(v->assistant.setEmotion(3));
 for(int i=0;i<modes.length;i++){final int n=i;Button btn=new Button(this);btn.setText(modes[i]);btn.setOnClickListener(v->{requestGeneration++;mode=n;getPreferences(0).edit().putInt("mode",n).apply();status.setText(modes[n]+" • Ready");assistant.setMode(n);assistant.setEmotion(0);});root.addView(btn);}
 Button apps=new Button(this);apps.setText("All apps");apps.setOnClickListener(v->{Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(Intent.CATEGORY_LAUNCHER);java.util.List<ResolveInfo> list=getPackageManager().queryIntentActivities(q,0);list.sort(new ResolveInfo.DisplayNameComparator(getPackageManager()));String[] labels=new String[list.size()];for(int j=0;j<labels.length;j++)labels[j]=list.get(j).loadLabel(getPackageManager()).toString();new AlertDialog.Builder(this).setTitle("Apps").setItems(labels,(d,j)->{ResolveInfo a=list.get(j);Intent launch=new Intent(Intent.ACTION_MAIN);launch.addCategory(Intent.CATEGORY_LAUNCHER);launch.setClassName(a.activityInfo.packageName,a.activityInfo.name);try{startActivity(launch);}catch(Exception e){Toast.makeText(this,"Unable to open app",0).show();}}).show();});root.addView(apps); Button chat=new Button(this);chat.setText("Talk to SUMAX");chat.setOnClickListener(v->{EditText input=new EditText(this);new AlertDialog.Builder(this).setTitle("SUMAX offline commands").setView(input).setPositiveButton("Send",(d,w)->respond(input.getText().toString())).setNegativeButton("Cancel",null).show();});root.addView(chat); Button voice=new Button(this);voice.setText("Voice input");voice.setOnClickListener(v->{Intent i=new Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);try{startActivityForResult(i,42);}catch(ActivityNotFoundException e){Toast.makeText(this,"Speech recognition unavailable",Toast.LENGTH_SHORT).show();}});root.addView(voice);Button config=new Button(this);config.setText("Online AI settings");config.setOnClickListener(v->configureOnline());root.addView(config);setContentView(root);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==42&&result==RESULT_OK&&data!=null){java.util.ArrayList<String> words=data.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty())respond(words.get(0));}}
 private void respond(String input){requestGeneration++;String q=input.trim().toLowerCase(java.util.Locale.ROOT);String answer;int emotion=1;if(q.equals("time")||q.equals("what time is it"))answer=java.text.DateFormat.getTimeInstance().format(new java.util.Date());else if(q.equals("date")||q.equals("what is the date"))answer=java.text.DateFormat.getDateInstance().format(new java.util.Date());else if(q.equals("hello")||q.equals("hi"))answer="Hello. "+modes[mode]+" is ready.";else if(q.equals("help"))answer="Try hello, time, date, or switch to Hunter, Shadow or Guardian.";else if(q.startsWith("switch to ")){int found=-1;for(int j=0;j<modes.length;j++)if(q.equals("switch to "+modes[j].toLowerCase(java.util.Locale.ROOT)))found=j;if(found>=0){mode=found;getPreferences(0).edit().putInt("mode",mode).apply();avatar.setMode(mode);answer=modes[mode]+" activated.";}else answer="Unknown mode.";}else{askOnline(input);return;}avatar.setEmotion(emotion);state.setText(modes[mode]+" • "+answer);if(speechReady)speech.speak(answer,android.speech.tts.TextToSpeech.QUEUE_FLUSH,null,"sumax-response");}
 private int requestGeneration;
 private void configureOnline(){EditText endpoint=new EditText(this);endpoint.setSingleLine(true);endpoint.setHint("https://your-server/chat");endpoint.setText(getPreferences(0).getString("endpoint",""));new AlertDialog.Builder(this).setTitle("Trusted HTTPS AI gateway").setMessage("Use your own trusted server. Unknown offline commands will be sent to this server. No API key is stored in the app.").setView(endpoint).setPositiveButton("Save",(d,w)->{String value=endpoint.getText().toString().trim();try{java.net.URI uri=new java.net.URI(value);if(!value.isEmpty()&&(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null))throw new Exception();getPreferences(0).edit().putString("endpoint",value).apply();}catch(Exception e){Toast.makeText(this,"Enter a valid HTTPS address",Toast.LENGTH_LONG).show();}}).setNegativeButton("Cancel",null).show();}
 private void askOnline(String input){String endpoint=getPreferences(0).getString("endpoint","");if(endpoint.isEmpty()){state.setText("Online AI is not configured. Offline commands remain available.");avatar.setEmotion(2);return;}final int generation=++requestGeneration;final String selected=modes[mode];avatar.setEmotion(2);state.setText("Thinking…");new Thread(()->{String answer;boolean success=false;javax.net.ssl.HttpsURLConnection connection=null;try{connection=(javax.net.ssl.HttpsURLConnection)new java.net.URL(endpoint).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(10000);connection.setReadTimeout(20000);connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");org.json.JSONObject body=new org.json.JSONObject();body.put("message",input);body.put("mode",selected);try(java.io.OutputStream out=connection.getOutputStream()){out.write(body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}if(connection.getResponseCode()!=200)throw new java.io.IOException();try(java.io.InputStream in=connection.getInputStream();java.io.ByteArrayOutputStream buffer=new java.io.ByteArrayOutputStream()){byte[] bytes=new byte[4096];int n;while((n=in.read(bytes))!=-1){if(buffer.size()+n>65536)throw new java.io.IOException();buffer.write(bytes,0,n);}answer=new org.json.JSONObject(buffer.toString("UTF-8")).getString("reply");success=true;}}catch(Exception e){answer="Online AI unavailable. Try help for offline commands.";}finally{if(connection!=null)connection.disconnect();}final String reply=answer;final boolean ok=success;runOnUiThread(()->{if(isFinishing()||isDestroyed()||generation!=requestGeneration)return;avatar.setEmotion(ok?1:2);state.setText(reply);if(speechReady)speech.speak(reply,android.speech.tts.TextToSpeech.QUEUE_FLUSH,null,"sumax-online");});}).start();}
 @Override protected void onDestroy(){if(speech!=null){speech.stop();speech.shutdown();}super.onDestroy();}
}
